INSERT INTO _migration_588_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_body_b003_002', 'topic_wassce_intsci_body', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The part of the brain responsible for balance and the coordination of body movement is the', 'multiple_choice', NULL, '["A. cerebrum","B. medulla oblongata","C. cerebellum","D. spinal cord"]', 'C', 'The cerebellum, at the back of the brain, coordinates muscular movement and maintains balance and posture. The cerebrum handles thought and voluntary actions, the medulla oblongata controls involuntary actions such as heartbeat and breathing, and the spinal cord is not part of the brain. Therefore the correct answer is C: cerebellum.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO3', NULL, NULL, NULL),
('q_wisc_body_b003_003', 'topic_wassce_intsci_body', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A student''s heart beats 72 times per minute. Calculate the total number of heartbeats during a 2-hour examination.', 'calculation', NULL, NULL, '8,640 beats', 'Two hours is 2 × 60 = 120 minutes. Number of beats = 72 × 120 = 8,640. Answer: the heart beats 8,640 times during the examination.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_body_b003_004', 'topic_wassce_intsci_body', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The human skeleton and circulatory system work together to support and sustain the body.', 'structured', NULL, NULL, '(a) Any two of: supports the body and gives it shape; protects delicate organs such as the brain, heart and lungs; provides surfaces for muscle attachment to allow movement; produces blood cells in the bone marrow. (b) Oxygenated blood flows from the lungs through the pulmonary vein into the left atrium, passes into the left ventricle, and is then pumped out through the aorta to all parts of the body.', '(a) Any two of: supports the body and gives it shape; protects delicate organs such as the brain, heart and lungs; provides surfaces for muscle attachment to allow movement; produces blood cells in the bone marrow. (b) Oxygenated blood flows from the lungs through the pulmonary vein into the left atrium, passes into the left ventricle, and is then pumped out through the aorta to all parts of the body.', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL),
('q_wisc_reproduction_b003_001', 'topic_wassce_intsci_reproduction', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'In guinea pigs, black fur (B) is dominant over white fur (b). Two heterozygous guinea pigs (Bb) are crossed. What fraction of the offspring is expected to have white fur?', 'calculation', NULL, NULL, '1/4 (25%)', 'The cross Bb × Bb gives the genotypes BB, Bb, Bb and bb in equal proportions. Since black is dominant, the BB and Bb offspring are black and only the bb offspring are white — 1 out of 4. Answer: 1/4, or 25%, of the offspring are expected to have white fur.', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL),
('q_wisc_reproduction_b003_002', 'topic_wassce_intsci_reproduction', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Living things increase their numbers by reproduction.', 'structured', NULL, NULL, '(a) Asexual reproduction involves one parent and produces offspring that are genetically identical to that parent, while sexual reproduction involves the fusion of male and female gametes, usually from two parents, and produces offspring that show variation. (b) Asexual reproduction allows rapid multiplication when conditions are favourable; sexual reproduction produces variation, which helps the species adapt to changing conditions and resist disease.', '(a) Asexual reproduction involves one parent and produces offspring that are genetically identical to that parent, while sexual reproduction involves the fusion of male and female gametes, usually from two parents, and produces offspring that show variation. (b) Asexual reproduction allows rapid multiplication when conditions are favourable; sexual reproduction produces variation, which helps the species adapt to changing conditions and resist disease.', 'medium', '4', '4', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL),
('q_wisc_matter_b003_001', 'topic_wassce_intsci_matter', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following is an example of a chemical change?', 'multiple_choice', NULL, '["A. Melting of candle wax","B. Dissolving salt in water","C. Magnetising a steel needle","D. Rusting of an iron roofing sheet"]', 'D', 'Rusting forms a new substance, hydrated iron(III) oxide, and cannot easily be reversed, so it is a chemical change. Melting wax, dissolving salt and magnetising steel produce no new substance and are reversible physical changes. Therefore the correct answer is D: Rusting of an iron roofing sheet.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO3', NULL, NULL, NULL);
INSERT INTO _migration_588_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_wisc_body_b003_004_a', 'q_wisc_body_b003_004', 'a', 'State two functions of the human skeleton.', '2', 'Any two of: supports the body and gives it shape; protects delicate organs such as the brain, heart and lungs; provides surfaces for muscle attachment to allow movement; produces blood cells in the bone marrow.', '1'),
('sqp_q_wisc_body_b003_004_b', 'q_wisc_body_b003_004', 'b', 'Describe the path taken by oxygenated blood from the lungs to the rest of the body.', '3', 'Oxygenated blood flows from the lungs through the pulmonary vein into the left atrium, passes into the left ventricle, and is then pumped out through the aorta to all parts of the body.', '2'),
('sqp_q_wisc_reproduction_b003_002_a', 'q_wisc_reproduction_b003_002', 'a', 'Distinguish between asexual reproduction and sexual reproduction.', '2', 'Asexual reproduction involves one parent and produces offspring that are genetically identical to that parent, while sexual reproduction involves the fusion of male and female gametes, usually from two parents, and produces offspring that show variation.', '1'),
('sqp_q_wisc_reproduction_b003_002_b', 'q_wisc_reproduction_b003_002', 'b', 'State one advantage of each type of reproduction.', '2', 'Asexual reproduction allows rapid multiplication when conditions are favourable; sexual reproduction produces variation, which helps the species adapt to changing conditions and resist disease.', '2');
INSERT INTO _migration_588_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_588_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_588_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_588_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_588_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_588_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_588_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_588_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_588_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_588_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_588_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_588_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 4 THEN 1 ELSE 0 END;
